INSERT INTO `notices` (`id`,`title`,`body`,`severity`,`author_id`,`published_from`,`published_to`,`created_at`) VALUES
  (501,'Customs desk opening hours over the Whitsun weekend','The customs desk in Felixstowe will run a reduced rota on Saturday and Sunday. Movements that need a clearance decision before Tuesday should be lodged by 16:00 on Friday. The Rotterdam desk keeps its normal hours and will absorb urgent files.','info',4001,'2026-05-18 07:00:00','2026-05-27 23:59:59','2026-05-15 16:42:11'),
  (502,'Planned maintenance on the rail booking interface','The rail booking interface will be unavailable between 22:00 and 02:00 on Thursday while the carrier upgrades its side of the link. Bookings taken during that period are held in the queue and released automatically once the link returns.','warning',4108,'2026-07-08 06:00:00','2026-07-10 06:00:00','2026-07-06 11:05:38'),
  (503,'New settlement calendar in force from September','Settlement for road and rail movements moves from a weekly to a twice weekly cycle from the first of September. Invoices raised on a Monday are now collected on the Thursday of the same week, and invoices raised on a Thursday are collected on the following Monday. Account managers should tell customers on strategic terms before the first run so that direct debit mandates are reviewed in time. Nothing changes for sea and air movements, which stay on the monthly cycle.','info',4001,'2026-08-24 06:00:00',NULL,'2026-08-21 09:17:04');
