INSERT INTO `routing_rules` (`id`,`name`,`expression`,`priority`,`enabled`,`updated_by`,`updated_at`) VALUES
  (31,'Heavy road freight to the northern desk','shipment.weightKg > 1200 and shipment.mode == ''road''',10,1,4001,'2026-02-11 09:24:17'),
  (32,'Refrigerated sea freight to the cold chain desk','shipment.mode == ''sea'' and shipment.temperatureControlled == true',20,1,4101,'2026-03-04 15:41:52'),
  (33,'Air freight above two cubic metres to capacity planning','shipment.mode == ''air'' and shipment.volumeM3 >= 2.0',30,1,4114,'2026-03-27 10:08:36'),
  (34,'Rail movements from the German network','shipment.mode == ''rail'' and shipment.originCode.startsWith(''DE'')',40,1,4106,'2026-04-15 08:56:03'),
  (35,'Strategic accounts to the named account manager','account.tier == ''strategic''',50,1,4125,'2026-05-06 11:33:29'),
  (36,'Held movements older than two days to the customs desk','shipment.status == ''held'' and shipment.ageHours > 48',60,1,4103,'2026-05-29 14:12:41'),
  (37,'Suspended accounts to credit control','account.status == ''suspended'' or account.openOverdue > 0',70,1,4104,'2026-06-17 09:47:55'),
  (38,'Small parcels under sixty kilos to the courier queue','shipment.weightKg < 60 and shipment.mode == ''road''',80,1,4129,'2026-07-02 16:20:08'),
  (39,'Movements without a customs entry to the exceptions queue','shipment.customsEntry == null and shipment.destinationCode.startsWith(''GB'')',90,1,4118,'2026-07-24 10:05:44'),
  (40,'Everything else to the general desk','true',999,0,4108,'2026-08-12 08:31:19');
